/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import * as readline from 'readline'

// Valid error tokens
const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

// Validate address format
function isValidAddress(addr) {
  if (typeof addr !== 'string' || addr.length === 0) return false
  let colEnd = 0
  if (addr[0] >= 'A' && addr[0] <= 'Z') {
    colEnd = 1
    if (addr.length > 1 && addr[1] >= 'A' && addr[1] <= 'Z') {
      colEnd = 2
    }
  } else {
    return false
  }

  const rowPart = addr.slice(colEnd)
  if (!/^[1-9]\d{0,2}$/.test(rowPart)) return false
  const row = parseInt(rowPart, 10)
  return row >= 1 && row <= 999
}

// Convert address string to column index (A=0, B=1, ..., Z=25, AA=26, etc.)
function addressToColRow(addr) {
  const match = addr.match(/^([A-Z]{1,2})([0-9]{1,3})$/)
  if (!match) return null

  const col = match[1]
  const row = parseInt(match[2], 10)

  let colIdx = 0
  if (col.length === 1) {
    colIdx = col.charCodeAt(0) - 65
  } else {
    colIdx = (col.charCodeAt(0) - 65 + 1) * 26 + (col.charCodeAt(1) - 65)
  }

  return { col: colIdx, row }
}

// Convert col/row indices back to address
function colRowToAddress(col, row) {
  let addr = ''
  if (col < 26) {
    addr = String.fromCharCode(65 + col)
  } else {
    const firstCol = Math.floor((col - 26) / 26)
    const secondCol = (col - 26) % 26
    addr = String.fromCharCode(65 + firstCol) + String.fromCharCode(65 + secondCol)
  }
  return addr + row
}

// Parse a number literal
function parseNumber(str) {
  if (/^-?\d+(\.\d+)?$/.test(str)) {
    return parseFloat(str)
  }
  return null
}

// Tokenize a formula
function tokenize(formula) {
  const tokens = []
  let i = 0

  while (i < formula.length) {
    // Skip whitespace
    if (formula[i] === ' ' || formula[i] === '\t') {
      i++
      continue
    }

    // Numbers
    if (/\d/.test(formula[i])) {
      let j = i
      while (j < formula.length && /[\d.]/.test(formula[j])) {
        j++
      }
      tokens.push({ type: 'number', value: parseFloat(formula.slice(i, j)) })
      i = j
      continue
    }

    // Cell addresses and identifiers
    if (/[A-Za-z]/.test(formula[i])) {
      let j = i
      while (j < formula.length && /[A-Za-z0-9]/.test(formula[j])) {
        j++
      }
      const word = formula.slice(i, j).toUpperCase()

      if (word === 'TRUE') {
        tokens.push({ type: 'boolean', value: true })
      } else if (word === 'FALSE') {
        tokens.push({ type: 'boolean', value: false })
      } else if (/^[A-Z]{1,2}\d{1,3}$/.test(word)) {
        tokens.push({ type: 'address', value: word })
      } else {
        tokens.push({ type: 'name', value: word })
      }
      i = j
      continue
    }

    // Operators and special chars
    if (formula[i] === ':') {
      tokens.push({ type: 'colon' })
      i++
    } else if (formula[i] === '(') {
      tokens.push({ type: 'lparen' })
      i++
    } else if (formula[i] === ')') {
      tokens.push({ type: 'rparen' })
      i++
    } else if (formula[i] === ',') {
      tokens.push({ type: 'comma' })
      i++
    } else if (formula[i] === '^') {
      tokens.push({ type: 'op', value: '^' })
      i++
    } else if (formula[i] === '*') {
      tokens.push({ type: 'op', value: '*' })
      i++
    } else if (formula[i] === '/') {
      tokens.push({ type: 'op', value: '/' })
      i++
    } else if (formula[i] === '+') {
      tokens.push({ type: 'op', value: '+' })
      i++
    } else if (formula[i] === '-') {
      tokens.push({ type: 'op', value: '-' })
      i++
    } else if (formula[i] === '=') {
      if (i + 1 < formula.length && formula[i + 1] === '<') {
        tokens.push({ type: 'op', value: '=<' })
        i += 2
      } else {
        tokens.push({ type: 'op', value: '=' })
        i++
      }
    } else if (formula[i] === '<') {
      if (i + 1 < formula.length && formula[i + 1] === '>') {
        tokens.push({ type: 'op', value: '<>' })
        i += 2
      } else if (i + 1 < formula.length && formula[i + 1] === '=') {
        tokens.push({ type: 'op', value: '<=' })
        i += 2
      } else {
        tokens.push({ type: 'op', value: '<' })
        i++
      }
    } else if (formula[i] === '>') {
      if (i + 1 < formula.length && formula[i + 1] === '=') {
        tokens.push({ type: 'op', value: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'op', value: '>' })
        i++
      }
    } else {
      return null // Invalid character
    }
  }

  return tokens
}

// Parse formula into an AST
class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek() {
    return this.tokens[this.pos]
  }

  consume() {
    return this.tokens[this.pos++]
  }

  expect(type, value = null) {
    const token = this.peek()
    if (!token || token.type !== type || (value !== null && token.value !== value)) {
      return false
    }
    this.consume()
    return true
  }

  parse() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    if (left === null) return null

    while (this.peek() && this.peek().type === 'op' && 
           ['=', '<>', '<', '<=', '>', '>='].includes(this.peek().value)) {
      const op = this.consume().value
      const right = this.parseAdditive()
      if (right === null) return null
      left = { type: 'op', op, left, right }
    }

    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    if (left === null) return null

    while (this.peek() && this.peek().type === 'op' && 
           ['+', '-'].includes(this.peek().value)) {
      const op = this.consume().value
      const right = this.parseMultiplicative()
      if (right === null) return null
      left = { type: 'op', op, left, right }
    }

    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    if (left === null) return null

    while (this.peek() && this.peek().type === 'op' && 
           ['*', '/'].includes(this.peek().value)) {
      const op = this.consume().value
      const right = this.parsePower()
      if (right === null) return null
      left = { type: 'op', op, left, right }
    }

    return left
  }

  parsePower() {
    let left = this.parseUnary()
    if (left === null) return null

    if (this.peek() && this.peek().type === 'op' && this.peek().value === '^') {
      this.consume()
      const right = this.parsePower() // Right associative
      if (right === null) return null
      return { type: 'op', op: '^', left, right }
    }

    return left
  }

  parseUnary() {
    if (this.peek() && this.peek().type === 'op' && 
        ['+', '-'].includes(this.peek().value)) {
      const op = this.consume().value
      const operand = this.parseUnary()
      if (operand === null) return null
      return { type: 'unary', op, operand }
    }

    return this.parsePrimary()
  }

  parsePrimary() {
    const token = this.peek()
    if (!token) return null

    if (token.type === 'number') {
      this.consume()
      return { type: 'number', value: token.value }
    }

    if (token.type === 'boolean') {
      this.consume()
      return { type: 'boolean', value: token.value }
    }

    if (token.type === 'address') {
      this.consume()
      const addr = token.value

      // Check for range
      if (this.peek() && this.peek().type === 'colon') {
        this.consume()
        const token2 = this.peek()
        if (!token2 || token2.type !== 'address') {
          return null
        }
        this.consume()
        return { type: 'range', start: addr, end: token2.value }
      }

      return { type: 'address', value: addr }
    }

    if (token.type === 'name') {
      const name = this.consume().value

      if (this.peek() && this.peek().type === 'lparen') {
        this.consume()
        const args = []

        if (this.peek() && this.peek().type !== 'rparen') {
          while (true) {
            const arg = this.parseComparison()
            if (arg === null) return null
            args.push(arg)

            if (this.peek() && this.peek().type === 'comma') {
              this.consume()
            } else {
              break
            }
          }
        }

        if (!this.expect('rparen')) {
          return null
        }

        return { type: 'call', name, args }
      }

      // Bare word that's not a function - treat as address
      if (/^[A-Z]{1,2}\d{1,3}$/.test(name)) {
        return { type: 'address', value: name }
      }

      return null
    }

    if (token.type === 'lparen') {
      this.consume()
      const expr = this.parseComparison()
      if (expr === null || !this.expect('rparen')) {
        return null
      }
      return expr
    }

    return null
  }
}

// Evaluate AST
class Evaluator {
  constructor(cells) {
    this.cells = cells
    this.evaluating = new Set()
  }

  eval(ast) {
    if (ast.type === 'number') {
      return ast.value
    }

    if (ast.type === 'boolean') {
      return ast.value
    }

    if (ast.type === 'address') {
      if (!isValidAddress(ast.value)) {
        return '#REF!'
      }
      return this.evalAddress(ast.value)
    }

    if (ast.type === 'range') {
      if (!isValidAddress(ast.start) || !isValidAddress(ast.end)) {
        return '#REF!'
      }
      return this.expandRange(ast.start, ast.end)
    }

    if (ast.type === 'unary') {
      const val = this.eval(ast.operand)
      if (typeof val === 'string') return val // error
      const num = this.toNumber(val)
      if (typeof num === 'string') return num // error
      if (ast.op === '-') return -num
      return num
    }

    if (ast.type === 'op') {
      return this.evalOp(ast)
    }

    if (ast.type === 'call') {
      return this.evalCall(ast)
    }

    return '#ERR!'
  }

  evalAddress(addr) {
    if (this.evaluating.has(addr)) {
      return '#CYCLE!'
    }

    this.evaluating.add(addr)
    const result = this.cells[addr] !== undefined ? this.cells[addr].value : 0
    this.evaluating.delete(addr)

    return result
  }

  expandRange(start, end) {
    const s = addressToColRow(start)
    const e = addressToColRow(end)
    if (!s || !e) return '#REF!'

    const startCol = Math.min(s.col, e.col)
    const endCol = Math.max(s.col, e.col)
    const startRow = Math.min(s.row, e.row)
    const endRow = Math.max(s.row, e.row)

    const cells = []
    for (let c = startCol; c <= endCol; c++) {
      for (let r = startRow; r <= endRow; r++) {
        const addr = colRowToAddress(c, r)
        cells.push(this.evalAddress(addr))
      }
    }

    return cells
  }

  evalOp(ast) {
    const left = this.eval(ast.left)
    if (typeof left === 'string') return left

    const right = this.eval(ast.right)
    if (typeof right === 'string') return right

    const cmp = ['=', '<>', '<', '<=', '>', '>='].includes(ast.op)

    if (cmp) {
      return this.compare(left, right, ast.op)
    }

    const leftNum = this.toNumber(left)
    if (typeof leftNum === 'string') return leftNum

    const rightNum = this.toNumber(right)
    if (typeof rightNum === 'string') return rightNum

    if (ast.op === '+') {
      const result = leftNum + rightNum
      return isFinite(result) ? result : '#DIV/0!'
    } else if (ast.op === '-') {
      const result = leftNum - rightNum
      return isFinite(result) ? result : '#DIV/0!'
    } else if (ast.op === '*') {
      const result = leftNum * rightNum
      return isFinite(result) ? result : '#DIV/0!'
    } else if (ast.op === '/') {
      if (rightNum === 0) return '#DIV/0!'
      const result = leftNum / rightNum
      return isFinite(result) ? result : '#DIV/0!'
    } else if (ast.op === '^') {
      const result = Math.pow(leftNum, rightNum)
      return isFinite(result) ? result : '#DIV/0!'
    }

    return '#ERR!'
  }

  compare(left, right, op) {
    const leftType = typeof left === 'boolean' ? 2 : typeof left === 'string' ? 1 : 0
    const rightType = typeof right === 'boolean' ? 2 : typeof right === 'string' ? 1 : 0

    if (leftType !== rightType) {
      const cmp = leftType < rightType
      if (op === '=') return false
      if (op === '<>') return true
      if (op === '<') return cmp
      if (op === '<=') return cmp
      if (op === '>') return !cmp
      if (op === '>=') return !cmp
    }

    let result
    if (leftType === 0) {
      const cmp = left - right
      result = cmp < 0 ? -1 : cmp > 0 ? 1 : 0
    } else if (leftType === 1) {
      result = left < right ? -1 : left > right ? 1 : 0
    } else {
      result = left === right ? 0 : left ? 1 : -1
    }

    if (op === '=') return result === 0
    if (op === '<>') return result !== 0
    if (op === '<') return result < 0
    if (op === '<=') return result <= 0
    if (op === '>') return result > 0
    if (op === '>=') return result >= 0

    return false
  }

  toNumber(val) {
    if (typeof val === 'number') return val
    if (typeof val === 'boolean') return val ? 1 : 0
    if (typeof val === 'string') return '#VALUE!'
    if (Array.isArray(val)) return '#VALUE!'
    return '#VALUE!'
  }

  evalCall(ast) {
    const func = ast.name.toUpperCase()

    if (func === 'IF') {
      if (ast.args.length !== 3) return '#ERR!'

      const cond = this.eval(ast.args[0])
      if (typeof cond === 'string' && ERROR_TOKENS.has(cond)) return cond

      const condVal = typeof cond === 'boolean' ? cond : (typeof cond === 'number' ? cond !== 0 : false)

      if (condVal) {
        return this.eval(ast.args[1])
      } else {
        return this.eval(ast.args[2])
      }
    }

    if (ast.args.length === 0) return '#ERR!'

    const values = []
    for (const arg of ast.args) {
      const val = this.eval(arg)
      if (typeof val === 'string' && ERROR_TOKENS.has(val)) {
        return val
      }
      if (Array.isArray(val)) {
        values.push(...val)
      } else {
        values.push(val)
      }
    }

    if (func === 'SUM') {
      let sum = 0
      for (const val of values) {
        const num = this.toNumber(val)
        if (typeof num === 'string') return num
        sum += num
      }
      return sum
    } else if (func === 'COUNT') {
      let count = 0
      for (const val of values) {
        if (typeof val === 'number') count++
      }
      return count
    } else if (func === 'MIN') {
      if (values.length === 0) return '#ERR!'
      let min = null
      for (const val of values) {
        const num = this.toNumber(val)
        if (typeof num === 'string') return num
        if (min === null || num < min) min = num
      }
      return min
    } else if (func === 'MAX') {
      if (values.length === 0) return '#ERR!'
      let max = null
      for (const val of values) {
        const num = this.toNumber(val)
        if (typeof num === 'string') return num
        if (max === null || num > max) max = num
      }
      return max
    } else if (func === 'AVG') {
      if (values.length === 0) return '#ERR!'
      let sum = 0
      for (const val of values) {
        const num = this.toNumber(val)
        if (typeof num === 'string') return num
        sum += num
      }
      return sum / values.length
    } else if (func === 'ABS') {
      if (ast.args.length !== 1) return '#ERR!'
      const val = this.eval(ast.args[0])
      const num = this.toNumber(val)
      if (typeof num === 'string') return num
      return Math.abs(num)
    } else {
      return '#NAME?'
    }
  }
}

// Format value for output
function formatValue(val) {
  if (typeof val === 'string') return val // error or text
  if (typeof val === 'boolean') return val ? 'TRUE' : 'FALSE'
  if (typeof val === 'number') {
    if (!isFinite(val)) return '#DIV/0!'
    const str = val.toExponential(10)
    const match = str.match(/^(-?\d\.\d{10})e([+-]?\d+)$/)
    if (match) {
      const mantissa = parseFloat(match[1])
      const exp = parseInt(match[2], 10)
      const fullNum = mantissa * Math.pow(10, exp)
      const absNum = Math.abs(fullNum)

      if (absNum === 0) return '0'
      if (absNum < 1e-6 || absNum >= 1e21) {
        // Use exponential notation
        const sigFigs = val.toPrecision(10)
        return parseFloat(sigFigs).toString()
      }

      const sigFigs = val.toPrecision(10)
      return parseFloat(sigFigs).toString()
    }
    const sigFigs = val.toPrecision(10)
    return parseFloat(sigFigs).toString()
  }
  return String(val)
}

// Get cells referenced by a formula
function extractDeps(ast, deps) {
  if (!ast) return

  if (ast.type === 'address') {
    if (isValidAddress(ast.value)) {
      deps.add(ast.value)
    }
  } else if (ast.type === 'range') {
    if (isValidAddress(ast.start) && isValidAddress(ast.end)) {
      const s = addressToColRow(ast.start)
      const e = addressToColRow(ast.end)
      if (s && e) {
        const startCol = Math.min(s.col, e.col)
        const endCol = Math.max(s.col, e.col)
        const startRow = Math.min(s.row, e.row)
        const endRow = Math.max(s.row, e.row)

        for (let c = startCol; c <= endCol; c++) {
          for (let r = startRow; r <= endRow; r++) {
            deps.add(colRowToAddress(c, r))
          }
        }
      }
    }
  } else if (ast.type === 'op') {
    extractDeps(ast.left, deps)
    extractDeps(ast.right, deps)
  } else if (ast.type === 'unary') {
    extractDeps(ast.operand, deps)
  } else if (ast.type === 'call') {
    for (const arg of ast.args) {
      extractDeps(arg, deps)
    }
  }
}

async function main() {
  const args = process.argv.slice(2)

  if (args.length !== 1 || !['values', 'deps'].includes(args[0])) {
    process.stderr.write('error: usage: cli.js values|deps\n')
    process.exit(2)
  }

  const mode = args[0]

  // Read input
  const rl = readline.createInterface({
    input: process.stdin,
    output: undefined,
    terminal: false
  })

  const cells = {}
  const cellAsts = {}
  let lineNum = 0

  for await (const line of rl) {
    lineNum++

    // Strip leading spaces and tabs
    let content = line.replace(/^[ \t]+/, '')

    // Skip empty lines and comments
    if (content === '' || content.startsWith('#')) {
      continue
    }

    // Parse address and content
    const match = content.match(/^([A-Za-z]{1,2}[0-9]{1,3})[ \t]+(.*)$/)
    if (!match) {
      process.stderr.write(`error: line ${lineNum}: invalid cell address ${content.split(/[ \t]/)[0]}\n`)
      process.exit(2)
    }

    const addr = match[1].toUpperCase()
    const cellContent = match[2]

    if (!isValidAddress(addr)) {
      process.stderr.write(`error: line ${lineNum}: invalid cell address ${addr}\n`)
      process.exit(2)
    }

    if (cells[addr] !== undefined) {
      process.stderr.write(`error: line ${lineNum}: cell ${addr} is declared twice\n`)
      process.exit(2)
    }

    if (cellContent.startsWith('=')) {
      // Parse formula
      const formula = cellContent.slice(1)
      const tokens = tokenize(formula)

      if (tokens === null) {
        cells[addr] = { value: '#ERR!' }
        cellAsts[addr] = null
      } else {
        const parser = new Parser(tokens)
        const ast = parser.parse()

        if (!ast || parser.pos !== tokens.length) {
          cells[addr] = { value: '#ERR!' }
          cellAsts[addr] = null
        } else {
          cells[addr] = { value: null, ast }
          cellAsts[addr] = ast
        }
      }
    } else {
      // Parse literal
      const num = parseNumber(cellContent)
      if (num !== null) {
        cells[addr] = { value: num }
      } else if (ERROR_TOKENS.has(cellContent)) {
        cells[addr] = { value: cellContent }
      } else {
        cells[addr] = { value: cellContent }
      }
    }
  }

  // Evaluate cells
  const evaluator = new Evaluator(cells)

  for (const addr in cells) {
    if (cells[addr].value === null) {
      cells[addr].value = evaluator.eval(cells[addr].ast)
    }
  }

  // Sort addresses
  const addresses = Object.keys(cells).sort((a, b) => {
    const aPos = addressToColRow(a)
    const bPos = addressToColRow(b)
    if (aPos.col !== bPos.col) return aPos.col - bPos.col
    return aPos.row - bPos.row
  })

  if (mode === 'values') {
    for (const addr of addresses) {
      const val = cells[addr].value
      process.stdout.write(`${addr}=${formatValue(val)}\n`)
    }
  } else {
    for (const addr of addresses) {
      const deps = new Set()
      if (cellAsts[addr]) {
        extractDeps(cellAsts[addr], deps)
      }

      const depList = Array.from(deps).sort((a, b) => {
        const aPos = addressToColRow(a)
        const bPos = addressToColRow(b)
        if (aPos.col !== bPos.col) return aPos.col - bPos.col
        return aPos.row - bPos.row
      })

      process.stdout.write(`${addr}:`)
      for (const dep of depList) {
        process.stdout.write(` ${dep}`)
      }
      process.stdout.write('\n')
    }
  }

  process.exit(0)
}

main().catch(err => {
  process.stderr.write(`error: ${err.message}\n`)
  process.exit(2)
})
