      }
      return this.expandRange(ast.start, ast.end)
    }

    if (ast.type === 'unary') {
      const val = this.eval(ast.operand)
      if (typeof val === 'string') return val // error
      const num = this.toNumber(val)
      if (typeof num === 'string') return num // error
      if (ast.op === '-') return -num
