    const match = str.match(/^(-?\d\.\d{10})e([+-]?\d+)$/)
    if (match) {
      const mantissa = parseFloat(match[1])
      const exp = parseInt(match[2], 10)
      const fullNum = mantissa * Math.pow(10, exp)
      const absNum = Math.abs(fullNum)

      if (absNum === 0) return '0'
      if (absNum < 1e-6 || absNum >= 1e21) {
        // Use exponential notation
        const sigFigs = val.toPrecision(10)
        return parseFloat(sigFigs).toString()
      }

      const sigFigs = val.toPrecision(10)
      return parseFloat(sigFigs).toString()
    }
    const sigFigs = val.toPrecision(10)
    return parseFloat(sigFigs).toString()
  }
  return String(val)
}

// Get cells referenced by a formula
function extractDeps(ast, deps) {
  if (!ast) return

  if (ast.type === 'address') {
    if (isValidAddress(ast.value)) {
      deps.add(ast.value)
    }
  } else if (ast.type === 'range') {
    if (isValidAddress(ast.start) && isValidAddress(ast.end)) {
      const s = addressToColRow(ast.start)
      const e = addressToColRow(ast.end)
      if (s && e) {
        const startCol = Math.min(s.col, e.col)
        const endCol = Math.max(s.col, e.col)
        const startRow = Math.min(s.row, e.row)
        const endRow = Math.max(s.row, e.row)

        for (let c = startCol; c <= endCol; c++) {
          for (let r = startRow; r <= endRow; r++) {
            deps.add(colRowToAddress(c, r))
          }
        }
      }
    }
  } else if (ast.type === 'op') {
    extractDeps(ast.left, deps)
    extractDeps(ast.right, deps)
  } else if (ast.type === 'unary') {
    extractDeps(ast.operand, deps)
  } else if (ast.type === 'call') {
    for (const arg of ast.args) {
