{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet } from './sheet.js'
import { Engine } from './eval.js'
import { formatValue } from './value.js'
import { compareAddresses } from './address.js'

function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

function readStdin() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main() {
  const argv = process.argv.slice(2)
  if (argv.length !== 1 || (argv[0] !== 'values' && argv[0] !== 'deps')) {
    fail('usage: cli.js values|deps')
  }
  const mode = argv[0]

  const sheet = parseSheet(readStdin())
  if (sheet.error) fail(sheet.error)

  const engine = new Engine(sheet.cells)
  const addresses = [...sheet.cells.keys()].sort(compareAddresses)

  const out = []
  if (mode === 'values') {
    for (const addr of addresses) {
      out.push(`${addr}=${formatValue(engine.valueOf(addr))}\n`)
    }
  } else {
    for (const addr of addresses) {
      const deps = engine.depsOf(addr)
      out.push(deps.length ? `${addr}: ${deps.join(' ')}\n` : `${addr}:\n`)
    }
  }
  process.stdout.write(out.join(''))
  process.exit(0)
}

main()
"}

