{"file_path":"src/address.js","content":"/** Cell addresses: A1 .. ZZ999, upper-cased when read. */

const ADDRESS_RE = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Parses an address, returning { addr, col, row } or null when out of range. */
export function parseAddress(text) {
  const m = ADDRESS_RE.exec(text)
  if (!m) return null
  const letters = m[1].toUpperCase()
  const row = Number(m[2])
  if (row < 1) return null
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  return { addr: letters + String(row), col: col - 1, row }
}

export function isAddress(text) {
  return parseAddress(text) !== null
}

export function toAddress(col, row) {
  let letters = ''
  let c = col + 1
  while (c > 0) {
    const rem = (c - 1) % 26
    letters = String.fromCharCode(65 + rem) + letters
    c = Math.floor((c - 1) / 26)
  }
  return letters + String(row)
}

/** Every cell of the rectangle, ascending column then ascending row. */
export function expandRange(a, b) {
  const c0 = Math.min(a.col, b.col)
  const c1 = Math.max(a.col, b.col)
  const r0 = Math.min(a.row, b.row)
  const r1 = Math.max(a.row, b.row)
  const cells = []
  for (let c = c0; c <= c1; c++) {
    for (let r = r0; r <= r1; r++) cells.push(toAddress(c, r))
  }
  return cells
}

export function compareAddresses(x, y) {
  const a = parseAddress(x)
  const b = parseAddress(y)
  if (a.col !== b.col) return a.col - b.col
  return a.row - b.row
}
"}

