{"file_path":"src/value.js","content":"/** Values: numbers, text, booleans and errors, plus ranges as call arguments. */

export const ERRORS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const ERROR_SET = new Set(ERRORS)

export const DIV0 = err('#DIV/0!')
export const REF = err('#REF!')
export const VALUE = err('#VALUE!')
export const CYCLE = err('#CYCLE!')
export const NAME = err('#NAME?')
export const ERR = err('#ERR!')

export function num(n) {
  return { kind: 'num', n }
}
export function text(s) {
  return { kind: 'text', s }
}
export function bool(b) {
  return { kind: 'bool', b }
}
export function err(e) {
  return { kind: 'err', e }
}
export function range(cells) {
  return { kind: 'range', cells }
}

export function isError(v) {
  return v.kind === 'err'
}

export function isErrorToken(s) {
  return ERROR_SET.has(s)
}

/** A literal cell content, which is never a formula. */
export function literalValue(content) {
  if (content === '') return num(0)
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return num(Number(content))
  if (isErrorToken(content)) return err(content)
  return text(content)
}

/** A number in an arithmetic position, or an error value. */
export function toNumber(v) {
  if (v.kind === 'num') return v
  if (v.kind === 'bool') return num(v.b ? 1 : 0)
  if (v.kind === 'err') return v
  return VALUE
}

/** Guards a computed number against non-finite results. */
export function finite(n) {
  return Number.isFinite(n) ? num(n) : DIV0
}

export function formatValue(v) {
  switch (v.kind) {
    case 'num':
      return formatNumber(v.n)
    case 'text':
      return v.s
    case 'bool':
      return v.b ? 'TRUE' : 'FALSE'
    default:
      return v.e
  }
}

function formatNumber(n) {
  if (!Number.isFinite(n)) return String(n)
  if (n === 0) return '0'
  return String(Number(n.toPrecision(10)))
}
"}

