{"file_path":"src/formula.js","content":"/** The formula grammar: tokens and a recursive descent parser. */

const COMPARISONS = ['=', '<>', '<=', '>=', '<', '>']

/** Splits a formula body into tokens, or returns null when a character is bad. */
export function tokenize(src) {
  const tokens = []
  let i = 0
  while (i < src.length) {
    const ch = src[i]
    if (ch === ' ' || ch === '\t') {
      i++
      continue
    }
    if (ch >= '0' && ch <= '9') {
      const m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i))
      const raw = m[0]
      i += raw.length
      if (src[i] === '.') return null
      tokens.push({ type: 'num', value: Number(raw) })
      continue
    }
    if (/[A-Za-z]/.test(ch)) {
      const m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i))
      i += m[0].length
      tokens.push({ type: 'word', value: m[0].toUpperCase() })
      continue
    }
    if (ch === '(' || ch === ')' || ch === ',' || ch === ':') {
      tokens.push({ type: ch })
      i++
      continue
    }
    const two = src.slice(i, i + 2)
    if (two === '<>' || two === '<=' || two === '>=') {
      tokens.push({ type: 'op', value: two })
      i += 2
      continue
    }
    if ('^*/+-=<>'.includes(ch)) {
      tokens.push({ type: 'op', value: ch })
      i++
      continue
    }
    return null
  }
  return tokens
}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.i = 0
  }

  peek() {
    return this.tokens[this.i]
  }

  at(type, value) {
    const t = this.peek()
    if (!t || t.type !== type) return false
    return value === undefined || t.value === value
  }

  next() {
    return this.tokens[this.i++]
  }

  parseExpression() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    if (!left) return null
    while (this.peek() && this.peek().type === 'op' && COMPARISONS.includes(this.peek().value)) {
      const op = this.next().value
      const right = this.parseAdditive()
      if (!right) return null
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    if (!left) return null
    while (this.peek() && this.peek().type === 'op' && (this.peek().value === '+' || this.peek().value === '-')) {
      const op = this.next().value
      const right = this.parseMultiplicative()
      if (!right) return null
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    if (!left) return null
    while (this.peek() && this.peek().type === 'op' && (this.peek().value === '*' || this.peek().value === '/')) {
      const op = this.next().value
      const right = this.parsePower()
      if (!right) return null
      left = { type: 'bin', op, left, right }
    }
    return left
  }

  parsePower() {
    const left = this.parseUnary()
    if (!left) return null
    if (this.at('op', '^')) {
      this.next()
      const right = this.parsePower()
      if (!right) return null
      return { type: 'bin', op: '^', left, right }
    }
    return left
  }

  parseUnary() {
    if (this.at('op', '-') || this.at('op', '+')) {
      const op = this.next().value
      const operand = this.parseUnary()
      if (!operand) return null
      return { type: 'unary', op, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) return null
    if (t.type === 'num') {
      this.next()
      return { type: 'num', value: t.value }
    }
    if (t.type === '(') {
      this.next()
      const inner = this.parseExpression()
      if (!inner) return null
      if (!this.at(')')) return null
