import { parseAddress } from './address.js'
import { parseFormula, hasMisplacedRange } from './formula.js'

/**
 * Returns { cells } where cells maps an address to
 * { content, formula } (formula is null for a literal or a bad formula),
 * or { error } with the message of the first failure.
