export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const cells = new Map()
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i].replace(/^[ \t]+/, '')
    if (line === '' || line.startsWith('#')) continue

    let end = 0
    while (end < line.length && line[end] !== ' ' && line[end] !== '\t') end++
    const addressText = line.slice(0, end)
    let rest = line.slice(end)
    const skip = /^[ \t]+/.exec(rest)
    if (skip) rest = rest.slice(skip[0].length)

    const parsed = parseAddress(addressText)
    if (!parsed) {
      return { error: `line ${lineNo}: invalid cell address ${addressText}` }
    }
    if (cells.has(parsed.addr)) {
      return { error: `line ${lineNo}: cell ${parsed.addr} is declared twice` }
    }

    const cell = { content: rest, formula: null, bad: false }
    if (rest.startsWith('=')) {
      const ast = parseFormula(rest.slice(1))
      if (ast === null) {
        cell.bad = true
      } else {
        cell.formula = ast
        cell.misplacedRange = hasMisplacedRange(ast)
      }
    }
    cells.set(parsed.addr, cell)
  }
  return { cells }
}
