const VARIADIC = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'])
const FUNCTIONS = new Set([...VARIADIC, 'ABS', 'IF'])

function kindRank(v) {
  if (v.kind === 'num') return 0
  if (v.kind === 'text') return 1
  return 2
}

function compareText(a, b) {
  const x = [...a]
  const y = [...b]
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const ca = x[i].codePointAt(0)
    const cb = y[i].codePointAt(0)
    if (ca !== cb) return ca < cb ? -1 : 1
  }
  return x.length === y.length ? 0 : x.length < y.length ? -1 : 1
}

