  }

  evalNode(node) {
    switch (node.type) {
      case 'num':
        return num(node.value)
      case 'bool':
        return bool(node.value)
      case 'ref': {
        const parsed = parseAddress(node.name)
        if (!parsed) return REF
        return this.valueOf(parsed.addr)
      }
      case 'range': {
        const a = parseAddress(node.from)
        const b = parseAddress(node.to)
        if (!a || !b) return REF
        return range(expandRange(a, b).map((cell) => this.valueOf(cell)))
      }
      case 'unary': {
        const v = this.evalNode(node.operand)
        const n = toNumber(v)
        if (isError(n)) return n
        return node.op === '-' ? finite(-n.n) : finite(n.n)
      }
      case 'bin':
        return this.evalBinary(node)
      case 'call':
        return this.evalCall(node)
      default:
        return ERR
    }
  }

  evalBinary(node) {
    const left = this.evalNode(node.left)
    if (isError(left)) return left
    const right = this.evalNode(node.right)
    if (isError(right)) return right

    if (['=', '<>', '<', '<=', '>', '>='].includes(node.op)) {
      if (left.kind === 'range' || right.kind === 'range') return ERR
      return bool(applyComparison(node.op, orderOf(left, right)))
    }

    const a = toNumber(left)
    if (isError(a)) return a
    const b = toNumber(right)
    if (isError(b)) return b

    switch (node.op) {
      case '+':
        return finite(a.n + b.n)
      case '-':
        return finite(a.n - b.n)
      case '*':
        return finite(a.n * b.n)
      case '/':
        if (b.n === 0) return DIV0
        return finite(a.n / b.n)
      case '^':
        return finite(a.n ** b.n)
      default:
        return ERR
    }
  }

  evalCall(node) {
    const name = node.name
    if (!FUNCTIONS.has(name)) return NAME
    const arity = node.args.length
    if (VARIADIC.has(name) ? arity < 1 : name === 'IF' ? arity !== 3 : arity !== 1) {
      return ERR
    }

    if (name === 'IF') return this.evalIf(node.args)

    const values = []
    for (const arg of node.args) {
      const v = this.evalNode(arg)
      if (v.kind === 'range') {
        for (const item of v.cells) {
          if (isError(item)) return item
          values.push(item)
        }
      } else {
        if (isError(v)) return v
        values.push(v)
      }
    }

    if (name === 'COUNT') {
      return num(values.filter((v) => v.kind === 'num').length)
    }
    if (values.length === 0) return ERR

    const numbers = []
    for (const v of values) {
      const n = toNumber(v)
      if (isError(n)) return n
      numbers.push(n.n)
    }

    switch (name) {
      case 'SUM':
        return finite(numbers.reduce((s, x) => s + x, 0))
      case 'MIN':
        return finite(Math.min(...numbers))
      case 'MAX':
        return finite(Math.max(...numbers))
      case 'AVG':
        return finite(numbers.reduce((s, x) => s + x, 0) / numbers.length)
      default: {
        if (numbers.length !== 1) return ERR
        return finite(Math.abs(numbers[0]))
      }
    }
  }

  evalIf(args) {
    let cond = this.evalNode(args[0])
    if (cond.kind === 'range') {
      for (const item of cond.cells) if (isError(item)) return item
      if (cond.cells.length !== 1) return ERR
      cond = cond.cells[0]
    }
    if (isError(cond)) return cond
    const n = toNumber(cond)
    if (isError(n)) return n
    const branch = n.n !== 0 ? args[1] : args[2]
    const value = this.evalNode(branch)
    return value.kind === 'range' ? ERR : value
  }
}

function collectDeps(node, found) {
  switch (node.type) {
    case 'ref': {
      const parsed = parseAddress(node.name)
      if (parsed) found.add(parsed.addr)
      return
    }
    case 'range': {
      const a = parseAddress(node.from)
      const b = parseAddress(node.to)
      if (a && b) for (const cell of expandRange(a, b)) found.add(cell)
      return
    }
    case 'bin':
      collectDeps(node.left, found)
      collectDeps(node.right, found)
      return
    case 'unary':
      collectDeps(node.operand, found)
      return
    case 'call':
      for (const arg of node.args) collectDeps(arg, found)
      return
    default:
  }
}
